    """Repair isolated one-cell corruptions by continuing their surrounding region."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    singleton = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            size = 0
            while q:
                y, x = q.pop()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if size == 1:
                singleton.add((r, c))

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, c in singleton:
        # Ignore other isolated cells: they are corruptions too, not evidence
        # about the underlying color.
        around = [grid[y][x]
                  for y in range(max(0, r - 1), min(h, r + 2))
                  for x in range(max(0, c - 1), min(w, c + 2))
                  if (y, x) != (r, c) and (y, x) not in singleton]
        if not around:
            continue
        counts = Counter(around)

        # A corrupted cell can complete a solid 2x2 patch even when the
        # surrounding background is also common. Count such local continuities.
        square_support = Counter()
        for top in (r - 1, r):
            for left in (c - 1, c):
                if 0 <= top < h - 1 and 0 <= left < w - 1:
                    vals = [grid[y][x]
                            for y in (top, top + 1)
                            for x in (left, left + 1)
                            if (y, x) != (r, c) and (y, x) not in singleton]
                    if len(vals) == 3 and len(set(vals)) == 1:
                        square_support[vals[0]] += 1
        if square_support:
            best = max(square_support.values())
            candidates = [color for color, score in square_support.items() if score == best]
            if len(candidates) == 1:
                replacement = candidates[0]
            else:
                non_bg = [color for color in candidates if color != background]
                choices = non_bg if non_bg else candidates
                replacement = max(choices, key=lambda color: counts[color])
        else:
            best = max(counts.values())
            candidates = [color for color, score in counts.items() if score == best]
            if len(candidates) > 1:
                non_bg = [color for color in candidates if color != background]
                candidates = non_bg if non_bg else candidates
            replacement = max(candidates, key=lambda color: counts[color])
        out[r][c] = replacement
    return out
